-- 26 September 2026 daily current-affairs desk.
-- Original student-facing briefs verified against the linked official sources.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
  $$2026-09-26-tiger-reserve-management-effectiveness-cycle-six$$, $$2026-09-26$$,
  $$Sixth tiger-reserve management evaluation begins with a new waste criterion$$,
  $$The National Tiger Conservation Authority and Wildlife Institute of India began the sixth Management Effectiveness Evaluation of Tiger Reserves (MEE-TR). The cycle will cover all 58 tiger reserves and, for the first time, score solid-waste management separately.$$,
  $$This is a conservation-governance update. It tests what an evaluation system measures: management quality and outcomes, rather than a census of tiger numbers alone.$$,
  $$MEE is an evidence-based assessment of whether protected-area planning, resources and management actions are achieving conservation objectives. India started MEE in 2006; earlier cycles were completed in 2006, 2010, 2014, 2018 and 2022. The framework is adapted from the IUCN World Commission on Protected Areas approach.$$,
  $$Technical Manual for MEE-TR 2026 released; sixth evaluation cycle begins$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314795&lang=2&reg=48$$,
  $$Ministry of Environment, Forest and Climate Change / NTCA / Press Information Bureau$$, $$2026-09-25$$,
  $$["MEE-TR 2026 will cover all 58 Tiger Reserves.","The National Tiger Conservation Authority and Wildlife Institute of India are running the exercise.","Solid Waste Management is a separate evaluation criterion for the first time.","India's earlier MEE cycles were completed in 2006, 2010, 2014, 2018 and 2022."]$$::jsonb,
  $$[{"question":"What does MEE-TR assess?","answer":"How effectively a Tiger Reserve is managed to meet its conservation objectives."},{"question":"Which new standalone criterion is added in MEE-TR 2026?","answer":"Solid Waste Management."}]$$::jsonb,
  $${"title":"From reserve management to evaluation","steps":["A reserve sets conservation objectives and management plans.","Evaluators examine planning, resources, actions and evidence of outcomes.","Gaps such as waste handling or conflict management are identified.","Findings guide management priorities and resource allocation."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-paimana-central-sector-projects-august-report$$, $$2026-09-26$$,
  $$MoSPI’s PAIMANA report tracks 1,731 large Central-sector infrastructure projects$$,
  $$MoSPI reported that its PAIMANA platform tracked 1,731 ongoing Central-sector infrastructure projects costing ₹150 crore and above as of August 2026. Their aggregate revised cost was ₹33.60 lakh crore, with cumulative expenditure of ₹16.33 lakh crore.$$,
  $$This is useful for questions on infrastructure monitoring and official statistics. Do not read the dashboard total as all infrastructure spending in India: the release specifies its threshold and reporting coverage.$$,
  $$PAIMANA-PROJ is the renamed project-monitoring interface; PAIMANA-CRIP is the underlying Central Repository of Infrastructure Projects. The report says the data cover selected categories in the Department of Economic Affairs Harmonized Master List and depend on reporting by line ministries.$$,
  $$Flash Report on Central Sector Infrastructure Projects worth ₹150 crore and above$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314852&lang=2&reg=48$$,
  $$Ministry of Statistics and Programme Implementation / Press Information Bureau$$, $$2026-09-25$$,
  $$["PAIMANA tracked 1,731 ongoing projects worth ₹150 crore and above as of August 2026.","Their aggregate revised cost was ₹33.60 lakh crore and cumulative expenditure was ₹16.33 lakh crore.","PAIMANA-PROJ is the renamed monitoring interface, while PAIMANA-CRIP is the central repository/input layer.","The dashboard covers selected Harmonized Master List categories, not every infrastructure project in India."]$$::jsonb,
  $$[{"question":"Which ministry releases the PAIMANA flash report?","answer":"The Ministry of Statistics and Programme Implementation (MoSPI)."},{"question":"What does PAIMANA-CRIP provide?","answer":"The Central Repository of Infrastructure Projects that serves as the data/input layer."}]$$::jsonb,
  $${"title":"Infrastructure-monitoring data flow","steps":["Line ministries report project information.","PAIMANA-CRIP stores and standardises the underlying project data.","PAIMANA-PROJ displays monitoring and progress information.","MoSPI releases a threshold-based flash report for analysis and review."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-agnibaan-reusable-launch-vehicle-rdi-support$$, $$2026-09-26$$,
  $$TDB backs Agnikul’s reusable Agnibaan launch-vehicle development$$,
  $$The Technology Development Board signed an agreement to provide ₹200 crore of Research, Development and Innovation Fund support to Agnikul Cosmos for the Agnibaan reusable launch-vehicle project. The project aims to advance the technology from TRL 4 and above towards TRL 8.$$,
  $$This connects space technology with technology-readiness levels and public support for deep tech. A funding agreement for an RLV is not evidence that an operational reusable launch system already exists.$$,
  $$The release describes a proposed architecture with reusable upper-stage and descent-recovery elements, a semi-cryogenic liquid-propulsion system and a focus on repeatable launches. It says support is provided through optionally convertible debentures under the RDI Fund.$$,
  $$TDB-DST signs agreement with Agnikul Cosmos for RDI support to develop fully reusable Agnibaan launch vehicle$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314836&lang=2&reg=48$$,
  $$Technology Development Board, Department of Science and Technology / Press Information Bureau$$, $$2026-09-25$$,
  $$["TDB agreed ₹200 crore of RDI Fund support for Agnikul Cosmos.","The project is to move Agnibaan RLV from TRL 4 and above towards TRL 8.","The release describes optionally convertible debentures as the support instrument.","The proposed vehicle is intended to pursue full-system reusability, including controlled descent and recovery technologies."]$$::jsonb,
  $$[{"question":"What does TRL stand for in this project?","answer":"Technology Readiness Level."},{"question":"Which body signed the RDI support agreement?","answer":"The Technology Development Board (TDB) under the Department of Science and Technology."}]$$::jsonb,
  $${"title":"Maturing a reusable launch system","steps":["A launch-vehicle concept is developed and tested at lower readiness levels.","RDI finance supports propulsion, vehicle, guidance, descent and recovery work.","Technologies are validated towards higher readiness levels.","Successful maturation can enable repeatable and potentially lower-cost launches."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-arogya-manthan-digital-health-initiatives$$, $$2026-09-26$$,
  $$Aarogya Manthan launches new digital-health tools for AB PM-JAY and ABDM$$,
  $$At Aarogya Manthan 2026, the National Health Authority launched a National Healthcare Providers Registry mobile app, a Secure Data Environment and an Auto-Adjudication Framework for Ayushman Bharat PM-JAY. The event marked eight years of AB PM-JAY and five years of the Ayushman Bharat Digital Mission.$$,
  $$This is a health-governance item. It helps distinguish the financial-protection scheme AB PM-JAY from ABDM’s interoperable digital-health infrastructure.$$,
  $$The official release reports more than 60 crore beneficiaries under AB PM-JAY and more than 97.8 crore ABHAs created under ABDM. It also identifies the National Health Claims Exchange as a common digital platform intended to connect hospitals and insurers.$$,
  $$Aarogya Manthan 2026 marks eight years of AB PM-JAY and five years of ABDM$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314839&lang=1&reg=3$$,
  $$Ministry of Health and Family Welfare / National Health Authority / Press Information Bureau$$, $$2026-09-25$$,
  $$["Aarogya Manthan 2026 launched the National Healthcare Providers Registry mobile app, Secure Data Environment and Auto-Adjudication Framework.","AB PM-JAY is a health-assurance scheme; ABDM develops digital-health infrastructure.","The release reports over 60 crore AB PM-JAY beneficiaries.","It reports more than 97.8 crore ABHAs created under ABDM."]$$::jsonb,
  $$[{"question":"Which body organised Aarogya Manthan 2026?","answer":"The National Health Authority."},{"question":"What is the key difference between AB PM-JAY and ABDM?","answer":"AB PM-JAY provides health assurance, while ABDM builds the digital-health ecosystem."}]$$::jsonb,
  $${"title":"Digital health and health assurance","steps":["A beneficiary accesses care under a health-assurance scheme.","Providers and professionals are identified through digital registries.","Consent-aware data systems support secure records and claims processes.","Interoperability can improve portability, administration and continuity of care."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-pharma-medical-device-pli-progress$$, $$2026-09-26$$,
  $$Pharma and medical-device PLI schemes report investment and employment progress$$,
  $$The Department of Pharmaceuticals reported progress under its PLI schemes for bulk drugs, pharmaceuticals and medical devices. As of June 2026, 55 applicants, including 20 MSMEs, had been selected; the release reports ₹46,744 crore in actual investment and 1,21,294 jobs.$$,
  $$This is industrial-policy context. PLI links incentives to eligible production or sales; it is not simply a grant for every company in a sector.$$,
  $$The three schemes cover key starting materials, drug intermediates and active pharmaceutical ingredients; pharmaceuticals; and domestic medical-device manufacturing. The medical-device scheme was approved in 2020 with a total financial outlay of ₹3,420 crore, according to the release.$$,
  $$Production Linked Incentive Schemes have strengthened pharmaceutical, bulk-drug and medical-device manufacturing$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314746&lang=1&reg=48$$,
  $$Department of Pharmaceuticals, Ministry of Chemicals and Fertilizers / Press Information Bureau$$, $$2026-09-25$$,
  $$["The Department of Pharmaceuticals described PLI schemes for bulk drugs, pharmaceuticals and medical devices.","The release reports 55 selected applicants, including 20 MSMEs, as of June 2026.","It reports ₹46,744 crore in actual investment and 1,21,294 jobs.","The PLI scheme for domestic medical-device manufacturing was approved in 2020 with a ₹3,420 crore outlay."]$$::jsonb,
  $$[{"question":"Which department administers the cited pharma and medical-device PLI schemes?","answer":"The Department of Pharmaceuticals, Ministry of Chemicals and Fertilizers."},{"question":"What are APIs in the bulk-drug PLI context?","answer":"Active Pharmaceutical Ingredients."}]$$::jsonb,
  $${"title":"How a sectoral PLI supports manufacturing","steps":["Government identifies strategically important manufacturing segments.","Eligible firms invest and produce under scheme conditions.","Incentives are linked to eligible incremental production or sales.","Domestic capacity, supply resilience and employment can expand."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-india-japan-forest-management-capacity-project$$, $$2026-09-26$$,
  $$India–JICA forest-management capacity project enters its second phase$$,
  $$The Ministry of Environment, Forest and Climate Change launched work on the Capacity Enhancement for Effective Forest Management Project with JICA. The seven-year phase runs from 2025-26 to 2031-32 and has a stated outlay of ₹537.10 crore.$$,
  $$This is a forestry, climate and international-cooperation item. Its focus is capacity development and applied management, not the creation of a new protected area.$$,
  $$The release says JICA’s contribution is ₹440.42 crore and the Government of India share is ₹96.68 crore. The project includes training institutions, field applications, research, digital transformation, wood transformation and livelihood generation, with all States involved and priority for new participating States.$$,
  $$Capacity Enhancement for Effective Forest Management Project, in collaboration with JICA$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314681&lang=2&reg=48$$,
  $$Ministry of Environment, Forest and Climate Change / Press Information Bureau$$, $$2026-09-25$$,
  $$["The forest-management project is implemented from 2025-26 to 2031-32.","Its stated outlay is ₹537.10 crore: ₹440.42 crore from JICA and ₹96.68 crore from the Government of India.","It focuses on capacity building, research, field application and sustainable forest management.","The release says all States are involved, with priority for new participating States."]$$::jsonb,
  $$[{"question":"Which Japanese agency is collaborating on the forest-management project?","answer":"Japan International Cooperation Agency (JICA)."},{"question":"What is the stated duration of the project phase?","answer":"Seven years, from 2025-26 to 2031-32."}]$$::jsonb,
  $${"title":"Building forest-management capacity","steps":["India and JICA finance a multi-year capacity programme.","Training, research and pilot applications address field-management challenges.","Institutions and frontline personnel adopt region-specific practices.","Improved management supports biodiversity, climate resilience and livelihoods."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-bhuj-barauni-amrit-bharat-express$$, $$2026-09-26$$,
  $$Railways approves a tri-weekly Amrit Bharat Express between Bhuj and Barauni$$,
  $$Indian Railways approved a tri-weekly Amrit Bharat Express between Bhuj in Gujarat and Barauni in Bihar. The service will cover 2,532 km and pass through Gujarat, Rajasthan, Uttar Pradesh and Bihar.$$,
  $$This is a transport-connectivity and Indian-geography item. For prelims, retain the terminals, frequency and the States on the route rather than treating an operational timetable as a new railway-zone arrangement.$$,
  $$Train 19427 is the Bhuj–Barauni service and 19428 runs in the return direction. The release lists major stops including Ahmedabad, Kota, Mathura, Bareilly, Gorakhpur, Siwan, Hajipur, Muzaffarpur and Samastipur; it says the Bhuj service will operate on Monday, Wednesday and Saturday.$$,
  $$Indian Railways to introduce new tri-weekly Amrit Bharat Express between Bhuj and Barauni$$,
  $$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2314721&lang=1&reg=3$$,
  $$Ministry of Railways / Press Information Bureau$$, $$2026-09-25$$,
  $$["The service connects Bhuj in Gujarat with Barauni in Bihar.","It covers 2,532 km and runs through Gujarat, Rajasthan, Uttar Pradesh and Bihar.","Train 19427 is Bhuj–Barauni and Train 19428 is the return service.","The Bhuj–Barauni train is to run on Monday, Wednesday and Saturday."]$$::jsonb,
  $$[{"question":"Which two States contain the terminals of this Amrit Bharat Express?","answer":"Gujarat (Bhuj) and Bihar (Barauni)."},{"question":"What is the frequency of the new Bhuj–Barauni service?","answer":"Tri-weekly."}]$$::jsonb,
  $${"title":"A cross-country rail connection","steps":["A train service is approved between two terminal cities.","Its route links intermediate towns and States.","A scheduled frequency determines regular passenger availability.","The connection can improve inter-regional mobility and market access."]}$$::jsonb,
  $$published$$, now()
),
(
  $$2026-09-26-icar-industry-csr-agriculture-partnerships$$, $$2026-09-26$$,
  $$Agrinnovate India facilitates ICAR’s industry partnerships for agriculture CSR work$$,
  $$Agrinnovate India facilitated memoranda of understanding between ICAR and three industry partners—Pidilite Industries, Venkateshwara Hatcheries and Everest Instruments—for CSR-supported public-benefit work in agriculture and allied sectors.$$,
  $$This is an agriculture-innovation and institutional-linkage brief. It is useful for identifying ICAR’s commercialisation and industry-interface arm, rather than assuming that an MoU itself delivers a completed farm intervention.$$,
  $$The partnerships identify sustainable agri-food systems, climate-resilient agriculture, technology transfer, agri-startups, incubation, nutrition-sensitive agriculture, biofortification, processing, mechanisation and One Health among the possible cooperation areas. The release describes Agrinnovate India as ICAR’s agribusiness, innovation, technology-commercialisation and CSR fund-mobilising arm.$$,
  $$Agrinnovate India facilitates ICAR partnerships with industry for CSR support in agriculture$$,
  $$https://www.pib.gov.in/PressReleasePage.aspx?PRID=2314694&lang=2&reg=48$$,
  $$Ministry of Agriculture and Farmers Welfare / ICAR / Press Information Bureau$$, $$2026-09-25$$,
  $$["Agrinnovate India facilitated ICAR MoUs with Pidilite Industries, Venkateshwara Hatcheries and Everest Instruments.","The stated purpose is CSR support for agriculture and allied-sector public-benefit initiatives.","Agrinnovate India is ICAR's agribusiness, innovation, technology-commercialisation and CSR fund-mobilising arm.","Areas listed include climate-resilient agriculture, technology transfer, incubation, biofortification, processing and One Health."]$$::jsonb,
  $$[{"question":"Which institution's industry-interface arm is Agrinnovate India?","answer":"The Indian Council of Agricultural Research (ICAR)."},{"question":"Name one cooperation area cited in the MoUs.","answer":"For example, climate-resilient agriculture, technology transfer, agri-startups, biofortification or One Health."}]$$::jsonb,
  $${"title":"Connecting research, CSR and farm innovation","steps":["ICAR research identifies agricultural and allied-sector needs.","Agrinnovate India connects research with industry and CSR partners.","MoUs frame potential cooperation and resource support.","Projects can then pursue technology transfer, capacity building or public-benefit outcomes."]}$$::jsonb,
  $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = excluded.reviewed_at,
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
  $$2026-09-26-tiger-reserve-management-effectiveness-cycle-six$$,
  $$2026-09-26-paimana-central-sector-projects-august-report$$,
  $$2026-09-26-agnibaan-reusable-launch-vehicle-rdi-support$$,
  $$2026-09-26-arogya-manthan-digital-health-initiatives$$,
  $$2026-09-26-pharma-medical-device-pli-progress$$,
  $$2026-09-26-india-japan-forest-management-capacity-project$$,
  $$2026-09-26-bhuj-barauni-amrit-bharat-express$$,
  $$2026-09-26-icar-industry-csr-agriculture-partnerships$$
) and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict do nothing;
